import{z as B,x as p,o as e,c as d,q as l,j as s,D as E,d as o,s as i,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"LSTM 门控","description":"","frontmatter":{"title":"LSTM 门控","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lstm-gating.md","filePath":"llm/lstm-gating.md","lastUpdated":1791413859000}'),m={name:"llm/lstm-gating.md"};function _(A,a,h,c,T,f){const r=p("Mermaid");return e(),d("div",null,[a[2]||(a[2]=l('<h1 id="lstm-门控" tabindex="-1">LSTM 门控 <a class="header-anchor" href="#lstm-门控" aria-label="Permalink to &quot;LSTM 门控&quot;">​</a></h1><div class="epigraph"><p>把状态拆成可以逐维加的细胞，再用门控制写入、读出与遗忘；加法路径让时间轴上的增益可以接近 $1$。</p><footer>—— 据 Hochreiter &amp; Schmidhuber, Long Short-Term Memory, Neural Computation, 1997 整理</footer></div><p><a href="/llm/rnn-long-range">RNN 与长程依赖</a>把长程收成 \\(\\rho^k\\)。本课不重推 BPTT。缺口是：普通 \\(h_t=\\tanh(W_h h_{t-1}+\\cdots)\\) 的转移是乘法式的，很难把 \\(\\rho\\) 锁在 \\(1\\)。方法是 LSTM：细胞 \\(c_t\\) 以加法和逐维门更新，\\(h_t\\) 由 \\(c_t\\) 经输出门读出。GRU 是下一课的简化。本课不把门写成注意力权重，也不对全体过去做一次内容寻址。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>残差课在深度上引入加法旁路。时间轴上需要类似结构：让 \\(c_t\\) 可以选择「把 \\(c_{t-1}\\) 几乎原样留下」。普通 RNN 没有这条加法。LSTM 引入三个门——遗忘 \\(f_t\\)、输入 \\(i_t\\)、输出 \\(o_t\\)——取值在 \\((0,1)\\)，由当前 \\(x_t\\) 与 \\(h_{t-1}\\) 经 sigmoid 产生。细胞</p> \\[c_t=f_t\\odot c_{t-1}+i_t\\odot\\tilde c_t, \\]<p>\\(\\tilde c_t\\) 是候选写入。若 \\(f_t\\approx 1\\)、\\(i_t\\approx 0\\)，则 \\(c_t\\approx c_{t-1}\\)，反向 \\(\\partial c_t/\\partial c_{t-1}\\approx 1\\)（在那些维上）。缺口是这条<strong>可学习的恒等</strong>，不是更多层 tanh。</p><p>门是逐维的，不是对整个向量一个标量。模型可以在某些坐标上长期记忆，在另一些上快速改写。这与 LayerNorm 的逐特征复位不同：门决定<strong>是否传递过去</strong>，LN 决定<strong>当前尺度</strong>。</p><p><span class="marginnote">直觉类比：把细胞想象成一块逐格控制的白板——遗忘门是每格的「橡皮擦力度」，输入门是「这一步能不能写新字」，输出门是「外面能不能读这块板」。三件事分开控制，才能一边保留很早之前的旧格子、一边今天只改另一格。</span></p><h3 id="门不是-softmax-注意力" tabindex="-1">门不是 softmax 注意力 <a class="header-anchor" href="#门不是-softmax-注意力" aria-label="Permalink to &quot;门不是 softmax 注意力&quot;">​</a></h3><p>三个门各自对细胞的坐标做缩放，不在时间维上归一化，也不去读任意过去的 \\(h_s\\)。信息要进入 \\(c\\)，必须在当时通过输入门；漏掉的时间步没有事后「回头去查」。把 LSTM 理解成「已经有了注意力」，后课 Bahdanau 会变成重复。本课的记忆是一条递推的细胞，寻址仍是时间顺序的。</p><p><span class="marginnote">原始 LSTM 用常数误差转盘描述加法路径。后来的遗忘门（Gers 等）让细胞能主动清空，否则 \\(c\\) 会无限累积。本课取带遗忘门的通行写法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每步从 \\((h_{t-1},x_t)\\) 算出 \\(f_t,i_t,o_t,\\tilde c_t\\)，更新 \\(c_t\\)，再 \\(h_t=o_t\\odot\\tanh(c_t)\\)。参数是若干张仿射（可拼成一块矩阵乘）。反向沿 \\(c\\) 的加法路径回传，同时每步加上门对参数的局部导数。梯度裁剪仍常用，因为门与候选仍可能在短程上放大。初始化遗忘门偏置为正，使早期更倾向「记住」，是常见技巧。</p><p><span class="marginnote">为什么遗忘门偏置初始化为正几乎必开：取 \\(b=1\\) 时开局 \\(\\sigma(1)\\approx 0.73\\)，门天然偏向「保留」；若从 \\(0\\) 初始化，\\(\\sigma(0)=0.5\\)，等于每步有一半的旧记忆被随机冲掉，长程任务起点就差一截。这是一行设置换来数量级差别训练动态的典型例子。</span></p>',15)),(e(),s(n,null,{default:E(()=>[i(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20CPREV%5B%22c%20%E4%B8%8A%E4%B8%80%E6%97%B6%E5%88%BB%22%5D%20--%3E%20FGT%5B%22%E9%81%97%E5%BF%98%E9%97%A8%E7%BC%A9%E6%94%BE%22%5D%0A%20%20CAND%5B%22%E5%80%99%E9%80%89%E5%86%99%E5%85%A5%22%5D%20--%3E%20ING%5B%22%E8%BE%93%E5%85%A5%E9%97%A8%E7%BC%A9%E6%94%BE%22%5D%0A%20%20FGT%20--%3E%20CNOW%5B%22%E7%9B%B8%E5%8A%A0%E5%BE%97%E5%88%B0%20c_t%22%5D%0A%20%20ING%20--%3E%20CNOW%0A%20%20CNOW%20--%3E%20OUTG%5B%22%E8%BE%93%E5%87%BA%E9%97%A8%E8%AF%BB%E5%87%BA%20h_t%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[o("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"长程依赖变成「遗忘门长期接近 \\(1\\) 的那些维」。这比强迫 \\(\\|W_h\\|_2=1\\) 更容易优化，因为是否传递由数据决定，不必全局谱半径精确为 \\(1\\)。短程仍走候选与门的非线性，表达力不丢。代价是每步参数与状态大约是简单 RNN 的四倍量级，且仍不能沿时间并行。",-1)),a[5]||(a[5]=t("p",null,"细胞与隐状态分开，使「记得」不必等于「对外露出」：输出门可以关掉， \\(c\\) 仍在。这在需要长时间计数或开关的模式上有用。代价是多一份要保存的状态，BPTT 的内存按 \\(2n\\) 而不是 \\(n\\) 涨（粗算）。初始化与裁剪仍然需要：门在 \\(0/1\\) 两端饱和时，\\(\\sigma'\\) 接近 \\(0\\)，短程路径也会消失。",-1)),a[6]||(a[6]=t("p",null,"失败模式：遗忘门学成总是 \\(1\\)，细胞饱和；或总是 \\(0\\)，退化为短程网络。正则与截断 BPTT 仍会影响能学到多远。LSTM 是结构上的缓解，不是无限记忆定理。",-1)),a[7]||(a[7]=t("p",null,[t("span",{class:"marginnote"},"数字实例感受代价：隐层宽度 \\(d=512\\) 时，简单 RNN 每层一个 \\(512\\times512\\) 矩阵（约 26 万参数）；LSTM 把三个门加一个候选共四个仿射拼在一起，参数约 \\(4\\) 倍（约 105 万）——表达力和门控是用四倍参数与串行延迟换来的。")],-1)),(e(),s(n,null,{default:E(()=>[i(r,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E5%BD%93%E5%89%8D%E8%BE%93%E5%85%A5%E4%B8%8E%20h%20%E7%BB%8F%20sigmoid%22%5D%20--%3E%20F%5B%22%E9%81%97%E5%BF%98%E9%97%A8%20f%22%5D%0A%20%20SIG%20--%3E%20O%5B%22%E8%BE%93%E5%87%BA%E9%97%A8%20o%22%5D%0A%20%20F%20--%3E%20KEEP%5B%22f%20%E8%BF%91%201%EF%BC%9A%E9%80%9A%E9%81%93%E5%B8%B8%E5%BC%80%EF%BC%8C%E9%95%BF%E6%9C%9F%E8%AE%B0%E5%BF%86%22%5D%0A%20%20F%20--%3E%20WIPE%5B%22f%20%E8%BF%91%200%EF%BC%9A%E6%B8%85%E7%A9%BA%EF%BC%8C%E5%86%99%E5%85%A5%E6%96%B0%E5%86%85%E5%AE%B9%22%5D%0A%20%20O%20--%3E%20MUTE%5B%22o%20%E8%BF%91%200%EF%BC%9Ac%20%E4%BB%8D%E8%AE%B0%E5%BE%97%E4%BD%86%E4%B8%8D%E5%A4%96%E9%9C%B2%22%5D%0A%20%20KEEP%20--%3E%20SAT%5B%22%E5%A4%84%E5%A4%84%E8%BF%91%201%EF%BC%9A%E7%BB%86%E8%83%9E%E9%A5%B1%E5%92%8C%22%5D%0A%20%20WIPE%20--%3E%20DEG%5B%22%E5%A4%84%E5%A4%84%E8%BF%91%200%EF%BC%9A%E9%80%80%E5%8C%96%E6%88%90%E7%9F%AD%E7%A8%8B%E7%BD%91%E7%BB%9C%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不对照 GRU 的两个门，不写 seq2seq。下一课<a href="/llm/gru-vs-lstm">GRU 对照</a>用更少的门做同一件加法记忆。后课默认：需要跨许多步的状态时，用门控 RNN 而不是朴素 tanh 递推；记忆仍是一条细胞，不是对过去全体的读取。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LSTM 用加法更新细胞，遗忘门接近 \\(1\\) 时时间轴增益接近 \\(1\\)。</li><li>三个门逐维控制遗忘、写入、读出；不是时间维上的 softmax。</li><li>漏掉的时间步不能事后随机访问。</li><li>参数与状态更贵，递推仍串行。</li><li>出处：Hochreiter &amp; Schmidhuber, Neural Computation, 1997。</li></ul>',4))])}const C=B(m,[["render",_]]);export{g as __pageData,C as default};
